def main():
    rows = sorted(DATA, key=lambda r: (r[2], r[0]))
    out = Path(__file__).resolve().parent.parent / "songs.csv"
    with out.open("w", encoding="utf-8-sig", newline="") as f:
        w = csv.writer(f, delimiter=";")
        w.writerow(["nr", "serie", "songtitel", "jahr", "sender", "interpret", "komponist", "kategorie",
                    "youtube", "jahr_quelle", "status", "notiz"])
        for i, (serie, song, jahr, sender, interp, komp, kat, yt, q, notiz) in enumerate(rows, 1):
            w.writerow([f"{i:03d}", serie, song, jahr, sender, interp, komp, kat,
                        f"https://youtu.be/{yt}", q, "ok" if q in ("W", "F", "A") else "prüfen", notiz])
    print(f"{len(rows)} Einträge -> {out}")


if __name__ == "__main__":
    main()
